static inline void scene_frame(Framebuffer*f,int scene,int shade){
 const uint16_t*s=scene_pixels[(unsigned)scene<6?scene:0];
 for(int y=0;y<480;y++)for(int x=0;x<640;x++){
  uint16_t v=s[(y>>1)*320+(x>>1)];
  uint32_t r=((v>>11)&31)*255/31,g=((v>>5)&63)*255/63,b=(v&31)*255/31;
  f->pixels[y*640+x]=((r*(unsigned)shade/255)<<16)|((g*(unsigned)shade/255)<<8)|(b*(unsigned)shade/255);
 }
}
